// Generated by tools/extract-hook.js from Frontend/src/modules/Food/pages/restaurant/OrderDetails.jsx (OrderDetails), then edited by hand
// where the web code touched the DOM. The logic is the web page's own.
/* eslint-disable react-hooks/exhaustive-deps, no-unused-vars, no-empty */
import { useState, useEffect } from 'react'
import { useNavigate, useParams, useLocation } from '../../../lib/webRouter'
import useRestaurantBackNavigation from '../useRestaurantBackNavigation'
import * as Print from 'expo-print'
import * as Sharing from 'expo-sharing'
import { restaurantAPI } from '../../../api/restaurant'
import { getRestaurantItemLineTotal, resolveRestaurantItemUnitPrice } from '../../utils/restaurantOrderPricing'
import { navigator } from '../../../lib/webShim'

const debugLog = (...args) => {}

const debugWarn = (...args) => {}

const debugError = (...args) => {}

const toNumber = (value) => {
  const num = Number(value)
  return Number.isFinite(num) ? num : null
}

const firstNumber = (...values) => {
  for (const value of values) {
    const num = toNumber(value)
    if (num !== null) return num
  }
  return null
}

const firstText = (...values) => {
  for (const value of values) {
    if (typeof value === "string" && value.trim()) return value.trim()
  }
  return ""
}

const formatMoney = (value) => `₹${Number(value || 0).toFixed(2)}`

const formatDiscount = (value) => `-₹${Math.abs(Number(value || 0)).toFixed(2)}`

export function useOrderDetails() {
  const navigate = useNavigate()
  const goBack = useRestaurantBackNavigation()
  const { id: orderId } = useParams()
  const location = useLocation()
  
  // State for order data
  const [orderData, setOrderData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  
  // Toast state
  const [showToast, setShowToast] = useState(false)
  const [toastMessage, setToastMessage] = useState("")
  const [isGeneratingPDF, setIsGeneratingPDF] = useState(false)

  // Fetch order data from API
  useEffect(() => {
    const fetchOrder = async () => {
      try {
        setLoading(true)
        setError(null)
        
        let response;
        try {
          response = await restaurantAPI.getOrderById(orderId)
          if (!response.data?.success) throw new Error('Readable ID fetch failed')
        } catch (e) {
          const fallbackId = location.state?.mongoId
          if (fallbackId && fallbackId !== orderId) {
            response = await restaurantAPI.getOrderById(fallbackId)
          } else {
            throw e
          }
        }
        
        if (response.data?.success) {
          const order = response.data.data?.order || response.data.data
          if (!order) throw new Error('Order data is missing')
          const orderStatusRaw = String(order.status || order.orderStatus || "").toLowerCase()
          const pricing = order.pricing || {}
          const computedSubtotal = Array.isArray(order.items)
            ? order.items.reduce(
                (sum, item) => sum + getRestaurantItemLineTotal(item),
                0,
              )
            : 0

          const itemSubtotal =
            firstNumber(
              pricing.baseSubtotal,
              pricing.subtotal,
              pricing.itemsTotal,
              pricing.itemSubtotal,
              order.itemSubtotal,
              order.subtotal
            ) ?? computedSubtotal

          const taxes =
            firstNumber(
              pricing.tax,
              pricing.gst,
              order.tax,
              order.gst
            ) ?? 0

          const packagingFee = firstNumber(pricing.packagingFee, order.packagingFee) ?? 0
          const deliveryFee = firstNumber(pricing.deliveryFee, order.deliveryFee) ?? 0
          const platformFee = firstNumber(pricing.platformFee, order.platformFee) ?? 0
          const discount = firstNumber(pricing.discount, order.discount) ?? 0
          const couponDiscount = firstNumber(pricing.couponDiscount, order.couponDiscount) ?? 0
          const referralDiscount = firstNumber(pricing.referralDiscount, order.referralDiscount) ?? 0

          const total =
            firstNumber(
              pricing.total,
              order.totalAmount,
              order.total,
              order.amount
            ) ??
            Math.max(
              0,
              itemSubtotal + packagingFee
            )
          // Restaurant view: never show customer payment-due as their bill
          const paidAmount = total

          const addressParts = [
            order.address?.street,
            order.address?.area,
            order.address?.city,
            order.address?.state,
            order.address?.pincode
          ].filter(Boolean)

          const fullAddress =
            order.address?.formattedAddress ||
            order.address?.address ||
            order.deliveryAddress?.formattedAddress ||
            order.deliveryAddress?.address ||
            [
              order.deliveryAddress?.street,
              order.deliveryAddress?.city,
              order.deliveryAddress?.state,
              order.deliveryAddress?.zipCode
            ].filter(Boolean).join(", ") ||
            (addressParts.length > 0 ? addressParts.join(", ") : "") ||
            "Address not available"

          const customerName = firstText(
            order.userId?.name,
            order.customerName,
            order.customer?.name,
            order.customerInfo?.name,
            order.deliveryAddress?.name,
            order.deliveryAddress?.fullName,
            order.address?.name
          ) || "Customer"

          const restaurantName = firstText(
            order.restaurantName,
            order.restaurant?.restaurantName,
            order.restaurant?.name,
            order.restaurantId?.restaurantName,
            order.restaurantId?.name,
            order.outletName
          ) || "Restaurant"

          const restLoc = order.restaurantId?.location || order.restaurant?.location || {};
          const resolvedRestaurantAddress =
            order.restaurantAddress ||
            order.restaurant_address ||
            restLoc.formattedAddress ||
            restLoc.address ||
            restLoc.addressLine1 ||
            [order.restaurantId?.area || restLoc.area, order.restaurantId?.city || restLoc.city].filter(Boolean).join(", ") ||
            "Restaurant Address";

          const rawPaymentStatus = String(
            order.payment?.status || order.paymentStatus || ""
          ).toLowerCase()
          const paymentMethod = String(order.payment?.method || "").toLowerCase()

          let paymentStatus = "PENDING"
          if (["completed", "paid", "captured", "success", "succeeded"].includes(rawPaymentStatus)) {
            paymentStatus = "PAID"
          } else if (["failed", "declined"].includes(rawPaymentStatus)) {
            paymentStatus = "FAILED"
          } else if (["refunded", "refund"].includes(rawPaymentStatus)) {
            paymentStatus = "REFUNDED"
          } else if (paymentMethod === "cash") {
            paymentStatus = orderStatusRaw === "delivered" ? "PAID" : "COD"
          }
          
          const statusLower = orderStatusRaw
          const reached = {
            confirmed: order.tracking?.confirmed?.status || ["confirmed", "preparing", "ready", "ready_for_pickup", "picked_up", "out_for_delivery", "delivered"].includes(statusLower),
            preparing: order.tracking?.preparing?.status || ["preparing", "ready", "ready_for_pickup", "picked_up", "out_for_delivery", "delivered"].includes(statusLower),
            ready: order.tracking?.ready?.status || ["ready", "ready_for_pickup", "picked_up", "out_for_delivery", "delivered"].includes(statusLower),
            outForDelivery: order.tracking?.outForDelivery?.status || ["picked_up", "out_for_delivery", "delivered"].includes(statusLower),
            delivered: order.tracking?.delivered?.status || statusLower === "delivered"
          }

          // Transform API order data to match component structure
          const transformedOrder = {
            id: order.orderId || order._id,
            status: orderStatusRaw.toUpperCase() || 'PENDING',
            date: new Date(order.createdAt).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }),
            time: new Date(order.createdAt).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true }),
            restaurant: restaurantName,
            address: resolvedRestaurantAddress,
            orderType: order.orderType || 'delivery',
            customer: {
              name: customerName,
              orderCount: order.userId?.orderCount || 1,
              location: order.orderType === 'takeaway' ? 'Self-Pickup Order' : fullAddress,
              distance: order.orderType === 'takeaway' ? '' : (order.deliveryDistance ? `${order.deliveryDistance} km` : '')
            },
            items: order.items?.map(item => ({
              name: item.name,
              quantity: item.quantity,
              price: resolveRestaurantItemUnitPrice(item),
              image: item.image,
              type: item.isVeg || item.foodType === 'Veg' ? 'Veg' : 'Non-Veg',
              variantName: item.variantName || ''
            })) || [],
            billing: {
              itemSubtotal,
              taxes,
              packagingFee,
              deliveryFee,
              platformFee,
              discount,
              couponDiscount,
              referralDiscount,
              total,
              paidAmount,
              paymentStatus
            },
            deliveryPartnerId: order.deliveryPartnerId || order.dispatch?.deliveryPartnerId || null,
            dispatchStatus: order.dispatch?.status || null,
            reason: order.cancellationReason || '',
            restaurantNote: order.restaurantNote || '',
            timeline: [
              { event: 'Order placed', timestamp: new Date(order.createdAt).toLocaleString('en-GB'), status: 'completed' },
              ...(reached.confirmed ? [{ event: 'Order confirmed', timestamp: order.tracking?.confirmed?.timestamp ? new Date(order.tracking.confirmed.timestamp).toLocaleString('en-GB') : '', status: 'completed' }] : []),
              ...(reached.preparing ? [{ event: 'Preparing', timestamp: order.tracking?.preparing?.timestamp ? new Date(order.tracking.preparing.timestamp).toLocaleString('en-GB') : '', status: 'completed' }] : []),
              ...(reached.ready ? [{ event: 'Ready for pickup', timestamp: order.tracking?.ready?.timestamp ? new Date(order.tracking.ready.timestamp).toLocaleString('en-GB') : '', status: 'completed' }] : []),
              ...(reached.outForDelivery ? [{ event: 'Out for delivery', timestamp: order.tracking?.outForDelivery?.timestamp ? new Date(order.tracking.outForDelivery.timestamp).toLocaleString('en-GB') : '', status: 'completed' }] : []),
              ...(reached.delivered ? [{ event: 'Delivered', timestamp: order.tracking?.delivered?.timestamp ? new Date(order.tracking.delivered.timestamp).toLocaleString('en-GB') : '', status: 'completed' }] : []),
              ...(statusLower === 'cancelled' ? [{ event: 'Cancelled', timestamp: order.cancelledAt ? new Date(order.cancelledAt).toLocaleString('en-GB') : '', status: 'rejected', reason: order.cancellationReason }] : [])
            ]
          }
          
          setOrderData(transformedOrder)
        } else {
          throw new Error('Order not found')
        }
      } catch (err) {
        debugError('Error fetching order:', err)
        setError(err.response?.data?.message || err.message || 'Failed to fetch order')
        setOrderData(null)
      } finally {
        setLoading(false)
      }
    }

    if (orderId) {
      fetchOrder()
    }
  }, [orderId])

  // Lenis smooth scrolling

  const handleCopyOrderId = () => {
    if (!orderData?.id) return
    navigator.clipboard.writeText(orderData.id)
    setToastMessage("Order ID copied to clipboard")
    setShowToast(true)
    setTimeout(() => setShowToast(false), 2000)
  }

  // The web builds the receipt with jsPDF + autotable (same sections, same order). Here the same content is laid out as HTML,
  // rendered to a PDF by the system print engine (expo-print) and handed to the share sheet.
  const handlePrintReceipt = async () => {
    try {
      setIsGeneratingPDF(true)
      setToastMessage("Generating receipt...")
      setShowToast(true)

      // Small delay to show the toast
      await new Promise(resolve => setTimeout(resolve, 300))

      if (!orderData) {
        throw new Error("Order data not found")
      }

      const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      const b = orderData.billing || {}
      const statusColor =
        orderData.status === "REJECTED" || orderData.status === "CANCELLED" ? '#dc2626'
        : orderData.status === "DELIVERED" ? '#16a34a' : '#000'
      const itemRows = (orderData.items || []).map(item =>
        `<tr><td>${esc(item.quantity)}x</td><td>${esc(item.name)}</td><td>${esc(item.type || "-")}</td><td>${esc(formatMoney(item.price))}</td></tr>`
      ).join('')
      const billRows = [
        ["Item Subtotal:", formatMoney(b.itemSubtotal)],
        ["Taxes:", formatMoney(b.taxes)],
      ]
      if (Number(b.packagingFee) > 0) billRows.push(["Packaging Fee:", formatMoney(b.packagingFee)])
      if (Number(b.deliveryFee) > 0) billRows.push(["Delivery Fee:", formatMoney(b.deliveryFee)])
      if (Number(b.platformFee) > 0) billRows.push(["Platform Fee:", formatMoney(b.platformFee)])
      if (Number(b.discount) > 0) billRows.push(["Discount:", formatDiscount(b.discount)])
      if (Number(b.couponDiscount) > 0) billRows.push(["Coupon Discount:", formatDiscount(b.couponDiscount)])
      if (Number(b.referralDiscount) > 0) billRows.push(["Referral Discount:", formatDiscount(b.referralDiscount)])
      const billHtml = billRows.map(([l, v]) => `<div class="row"><span>${esc(l)}</span><span>${esc(v)}</span></div>`).join('')
      const timelineHtml = (orderData.timeline || []).map(event => {
        const color = event.status === "completed" ? '#16a34a' : event.status === "rejected" ? '#dc2626' : '#9ca3af'
        return `<div class="ev"><span class="dot" style="background:${color}"></span><div><b>${esc(event.event)}</b><div class="ts">${esc(event.timestamp || "-")}</div></div></div>`
      }).join('')
      const html = `<html><head><meta name="viewport" content="width=device-width, initial-scale=1"/><style>
        body{font-family:Helvetica,Arial,sans-serif;color:#000;padding:24px;font-size:12px}
        h1{font-size:20px;text-align:center;margin:0 0 4px}h2{font-size:15px;margin:14px 0 6px}
        .c{text-align:center}hr{border:0;border-top:1px solid #000;margin:12px 0}
        table{width:100%;border-collapse:collapse}th{background:#374151;color:#fff;text-align:left;font-size:11px}
        th,td{border:1px solid #9ca3af;padding:4px 6px;font-size:11px}
        .row{display:flex;justify-content:space-between;padding:2px 0}
        .tot{border-top:1px dashed #000;margin-top:6px;padding-top:6px;font-weight:bold;font-size:13px}
        .ev{display:flex;gap:8px;margin:6px 0}.dot{width:8px;height:8px;border-radius:4px;margin-top:4px}
        .ts{color:#646464;font-size:10px}.foot{text-align:center;color:#646464;font-style:italic;font-size:10px;margin-top:24px}
      </style></head><body>
        <h1>${esc(orderData.restaurant)}</h1><div class="c">${esc(orderData.address)}</div>
        <h1 style="margin-top:16px">ORDER RECEIPT</h1><hr/>
        <div><b>Order ID:</b> ${esc(orderData.id)}</div>
        <div><b>Date &amp; Time:</b> ${esc(orderData.date)}, ${esc(orderData.time)}</div>
        <div><b>Status:</b> <span style="color:${statusColor}">${esc(orderData.status)}</span></div>
        <hr/><h2>CUSTOMER DETAILS</h2>
        <div><b>Name:</b> ${esc(orderData.customer?.name)}</div>
        <div><b>Location:</b> ${esc(orderData.customer?.location || "-")}</div>
        <div><b>Distance:</b> ${esc(orderData.customer?.distance || "-")}</div>
        <hr/><h2>ITEM DETAILS</h2>
        <table><thead><tr><th>Qty</th><th>Item Name</th><th>Type</th><th>Price</th></tr></thead><tbody>${itemRows}</tbody></table>
        <hr/><h2>BILL DETAILS</h2>${billHtml}
        <div class="row tot"><span>Total Bill:</span><span>${esc(formatMoney(b.total))}</span></div>
        ${Number(b.paidAmount) > 0 ? `<div class="row"><span>Amount Paid:</span><span>${esc(formatMoney(b.paidAmount))}</span></div>` : ''}
        <div style="font-size:11px;margin-top:4px">Payment Status: ${esc(b.paymentStatus)}</div>
        ${orderData.reason ? `<hr/><div style="color:#dc2626"><b>REASON:</b><div>${esc(orderData.reason)}</div></div>` : ''}
        <hr/><h2>ORDER TIMELINE</h2>${timelineHtml}
        <div class="foot">Thank you for your business!<br/>Generated on: ${esc(new Date().toLocaleString())}</div>
      </body></html>`

      const { uri } = await Print.printToFileAsync({ html })
      if (await Sharing.isAvailableAsync()) {
        await Sharing.shareAsync(uri, { mimeType: 'application/pdf', dialogTitle: `Order_Receipt_${orderData.id}`, UTI: 'com.adobe.pdf' })
      }

      // Show success message
      setToastMessage("Receipt downloaded successfully!")
      setShowToast(true)
      setTimeout(() => setShowToast(false), 2000)
    } catch (error) {
      debugError("Error generating PDF:", error)
      setToastMessage(`Failed: ${error.message || "Unknown error"}`)
      setShowToast(true)
      setTimeout(() => setShowToast(false), 3000)
    } finally {
      setIsGeneratingPDF(false)
    }
  }

  const getStatusColor = (status) => {
    switch (status) {
      case "REJECTED":
      case "CANCELLED":
        return "bg-red-700 text-white"
      case "DELIVERED":
        return "bg-green-600 text-white"
      default:
        return "bg-gray-600 text-white"
    }
  }

  // Loading state

  return {
    navigate,
    goBack,
    orderId,
    location,
    orderData,
    setOrderData,
    loading,
    setLoading,
    error,
    setError,
    showToast,
    setShowToast,
    toastMessage,
    setToastMessage,
    isGeneratingPDF,
    setIsGeneratingPDF,
    handleCopyOrderId,
    handlePrintReceipt,
    getStatusColor,
    toNumber,
    firstNumber,
    firstText,
    formatMoney,
    formatDiscount,
  }
}
